package schema

import (
	"time"

	"entgo.io/ent"
	"entgo.io/ent/schema/field"
	"entgo.io/ent/schema/mixin"
	"github.com/google/uuid"
)

// BaseMixin gives every entity:
//   - id uuid PK (generated by app, not DB, so we don't need a DB extension)
//   - created_at default now()
//   - updated_at default now() updated on every Update*
//
// We do NOT include soft-delete: MVP rows are either really gone or
// status-flagged in their own column. Re-introducing soft-delete later is
// straightforward via a separate mixin.
type BaseMixin struct{ mixin.Schema }

func (BaseMixin) Fields() []ent.Field {
	return []ent.Field{
		field.UUID("id", uuid.UUID{}).
			Default(uuid.New).
			Immutable(),
		field.Time("created_at").
			Default(time.Now).
			Immutable(),
		field.Time("updated_at").
			Default(time.Now).
			UpdateDefault(time.Now),
	}
}
